<?php require '../includes/auth.php';require '../includes/header.php';$u=guard('employee');
$s=db()->prepare("SELECT * FROM payslips WHERE employee_id=? AND status='Published' ORDER BY year DESC,month DESC,revision DESC");$s->execute([$u['id']]);page_head('My Payslips',[],$u);?>
<div class="card table-responsive"><table class="table mb-0"><tr><th>Period</th><th>Gross</th><th>Net Pay</th><th></th></tr><?php foreach($s as $p){?><tr><td><?=date('F',mktime(0,0,0,$p['month'],1)).' '.$p['year']?><?=$p['revision']?' <span class="badge text-bg-warning">Rev '.$p['revision'].'</span>':''?></td><td><?=money($p['gross'])?></td><td><?=money($p['net'])?></td><td><a class="btn btn-sm btn-primary" href="payslip.php?id=<?=$p['id']?>">View / PDF</a></td></tr><?php }if(!$s->rowCount())echo'<tr><td colspan=4 class="text-center text-muted p-4">No published payslips yet</td></tr>';?></table></div><?php page_foot();
